DO $$ DECLARE fn text; BEGIN SELECT pg_get_functiondef(oid) INTO fn FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='get_public_store_product'; IF position('SELECT id, name, description, price, image_url' IN fn)=0 THEN RAISE EXCEPTION 'Unexpected catalog detail definition'; END IF; fn := replace(fn, 'SELECT id, name, description, price, image_url', 'SELECT id, name, description, price, compare_at_price, made_to_order, lead_time_days, image_url'); EXECUTE fn;
SELECT pg_get_functiondef(oid) INTO fn FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='get_public_quote_by_id'; fn := replace(fn, '''product_name'', COALESCE((SELECT name FROM products WHERE id = qi.product_id), '''')', '''product_name'', qi.product_name'); EXECUTE fn; END $$;
